import java.util.*;

class Solution {
  public List<List<Integer>> pathSum(TreeNode root, int targetSum) {
    List<List<Integer>> ans = new ArrayList<>();
    walk(root, targetSum, new ArrayList<>(), ans);
    return ans;
  }

  private void walk(TreeNode node, int remaining, List<Integer> path, List<List<Integer>> ans) {
    if (node == null) return;
    path.add(node.val);
    remaining -= node.val;
    if (node.left == null && node.right == null && remaining == 0) ans.add(new ArrayList<>(path));
    walk(node.left, remaining, path, ans);
    walk(node.right, remaining, path, ans);
    path.remove(path.size() - 1);
  }
}
